DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.wrapped_summary(uuid)'::regprocedure) INTO definition; definition:=replace(definition,'WHEN ht.key=''sleep'' THEN round(avg(ci.value),2)','WHEN ht.key IN (''sleep'',''sleep7'') THEN round(avg(ci.value),2)'); EXECUTE definition; SELECT pg_get_functiondef('public.join_challenge(text)'::regprocedure) INTO definition; definition:=replace(definition,'SELECT max_members INTO cap FROM public.crews WHERE id=c.crew_id','SELECT CASE WHEN c.audience=''company'' THEN member_capacity ELSE max_members END INTO cap FROM public.crews WHERE id=c.crew_id'); EXECUTE definition; SELECT pg_get_functiondef('public.join_crew(text)'::regprocedure) INTO definition; definition:=replace(definition,'if not found then raise exception ''crew_not_found''; end if;','if not found then raise exception ''crew_not_found''; end if; if exists(select 1 from public.challenges ch where ch.crew_id=c.id) then perform public.join_challenge(_code); return c.id; end if;'); EXECUTE definition; SELECT pg_get_functiondef('public.validate_challenge_habit()'::regprocedure) INTO definition; definition:=replace(definition,'NEW.kind<>h.kind','NEW.kind<>h.kind OR NEW.unit IS DISTINCT FROM h.unit'); EXECUTE definition; END $$;